abstract public class NDXTransferToD365
{
    str environment = 'https://nxd365dev2cfe787f0628b85cfdevaos.axcloud.dynamics.com';
    str transferInfo = '';

    NDXAppRegistrationValues appRegValues;

    Niedax.AX.TableTransfer.TableTransfer tableTransfer;
    Niedax.D365.API.Models.D365_APIResponse response;

}

Method.Source:
protected void new()
{
    response = new Niedax.D365.API.Models.D365_APIResponse();
    environment = NDXHelperCommon::getD365EnvironmentURL();
}

public void startTransfer(Args _args)
{
    container con;

    if(_args.parm() == '')
    {
        throw Error('No environment set');
    }

    environment = _args.parm();

    if(_args.parmObject() != null && _args.parmObject() is NDXAppRegistrationValues)
    {
        appRegValues = _args.parmObject();
    }
    else
    {
        throw error("No object with App registration values");
    }
    tableTransfer = new Niedax.AX.TableTransfer.TableTransfer(appRegValues.parmTenantId(), appRegValues.parmClientId(), appRegValues.parmClientSecret());
    tableTransfer.D365UriEnvironment = new System.Uri(environment);
}

protected void dispTransferInfo()
{
    System.DateTime time = System.DateTime::Now;

    if(response.Success && response.RecId > 0)
    {
        info(strFmt("@NDX:NDXTableRecordTransferedSuccecfully", time.ToString() + ':' + response.Message));
    }
    else
    {
        warning(strFmt("@NDX:NDXTableRecordTransferedError", time.ToString() + ':' + response.Message));
    }
}
